Lexer::Lexer(std::string source, std::string fileName)
    : source_(std::move(source)), fileName_(std::move(fileName)) {}

bool Lexer::atEnd() const noexcept {
    return position_ >= source_.size();
}

char Lexer::peek(std::size_t offset) const noexcept {
    const auto index = position_ + offset;
    return index < source_.size() ? source_[index] : '\0';
}

char Lexer::advance() noexcept {
    const char value = source_[position_++];
    if (value == '\n') {
        ++line_;
        column_ = 1;
    } else {
        ++column_;
    }
    return value;
}

SourceLocation Lexer::currentLocation() const {
    return {fileName_, line_, column_};
}

Token Lexer::makeToken(TokenType type, std::string text, SourceLocation location,
                       bool formattedString) const {
    return {type, std::move(text), std::move(location), formattedString};
}

void Lexer::skipTrivia(std::vector<Token>& tokens, std::size_t parenthesisDepth) {
    for (;;) {
        while (!atEnd() && peek() != '\n' &&
               std::isspace(static_cast<unsigned char>(peek())) != 0) {
            advance();
        }
        if (peek() == '#') {
            while (!atEnd() && peek() != '\n') {
                advance();
            }
            continue;
        }
        if (peek() == '/' && peek(1) == '/') {
            while (!atEnd() && peek() != '\n') {
                advance();
            }
            continue;
        }
        if (peek() == '/' && peek(1) == '*') {
            const auto commentLocation = currentLocation();
            advance();
            advance();
            bool closed = false;
            while (!atEnd()) {
                if (peek() == '*' && peek(1) == '/') {
                    advance();
                    advance();
                    closed = true;
                    break;
                }
                if (peek() == '\n') {
                    const auto newlineLocation = currentLocation();
                    advance();
                    if (parenthesisDepth == 0) {
                        tokens.push_back(makeToken(TokenType::Newline, "\n", newlineLocation));
                    }
                } else {
                    advance();
                }
            }
            if (!closed) {
                throw DiagnosticError(commentLocation, "unterminated block comment");
            }
            continue;
        }
        return;
    }
}

Token Lexer::scanIdentifierOrInteger() {
    const auto location = currentLocation();
    const bool leadingDot = peek() == '.';
    const bool integer = leadingDot || (peek() >= '0' && peek() <= '9');
    std::string text;
    if (integer) {
        bool floating = leadingDot;
        const bool hexadecimal = !leadingDot && peek() == '0' &&
                                 (peek(1) == 'x' || peek(1) == 'X');
        if (leadingDot) {
            /* strtod-style leading-dot float, e.g. ".5"; the caller only
             * enters this branch on '.' when the next character is a
             * digit, so a digit sequence is guaranteed here. */
            text.push_back(advance());
            while (peek() >= '0' && peek() <= '9') text.push_back(advance());
        } else if (hexadecimal) {
            text.push_back(advance());
            text.push_back(advance());
            const auto digitStart = text.size();
            while ((peek() >= '0' && peek() <= '9') ||
                   (peek() >= 'a' && peek() <= 'f') ||
                   (peek() >= 'A' && peek() <= 'F')) {
                text.push_back(advance());
            }
            if (text.size() == digitStart) {
                throw DiagnosticError(location, "malformed hexadecimal integer literal");
            }
            if (peek() == 'u' || peek() == 'U') {
                text.push_back(advance());
            }
            if (isIdentifierPart(peek())) {
                while (isIdentifierPart(peek())) text.push_back(advance());
                throw DiagnosticError(location, "malformed hexadecimal integer literal");
            }
            const bool unsignedSuffix = text.back() == 'u' || text.back() == 'U';
            return makeToken(unsignedSuffix ? TokenType::UnsignedInteger : TokenType::Integer,
                             std::move(text), location);
        } else {
            while (peek() >= '0' && peek() <= '9') text.push_back(advance());
        }
        if (!leadingDot && peek() == '.' && peek(1) != '.') {
            /* strtod-style trailing-dot float, e.g. "5."; digits after the
             * dot are optional. */
            floating = true;
            text.push_back(advance());
            while (peek() >= '0' && peek() <= '9') text.push_back(advance());
        }
        if (peek() == 'e' || peek() == 'E') {
            floating = true;
            text.push_back(advance());
            if (peek() == '+' || peek() == '-') text.push_back(advance());
            if (peek() < '0' || peek() > '9') {
                throw DiagnosticError(location, "malformed floating-point literal");
            }
            while (peek() >= '0' && peek() <= '9') text.push_back(advance());
        }
        if (floating && peek() == 'f' && peek(1) == '6' && peek(2) == '4') {
            text.push_back(advance());
            text.push_back(advance());
            text.push_back(advance());
            if (isIdentifierPart(peek())) {
                throw DiagnosticError(location, "malformed floating-point literal");
            }
        }
        if (!floating && (peek() == 'u' || peek() == 'U')) {
            text.push_back(advance());
            return makeToken(TokenType::UnsignedInteger, std::move(text), location);
        }
        return makeToken(floating ? TokenType::Float : TokenType::Integer,
                         std::move(text), location);
    }
    while (isIdentifierPart(peek())) {
        text.push_back(advance());
    }

    std::string normalized;
    normalized.reserve(text.size());
    for (char value : text) {
        normalized.push_back(lowerAscii(value));
    }
    // The built-in class name remains distinct from primitive type keywords.
    if (text == "String") {
        return makeToken(TokenType::Identifier, std::move(text), location);
    }
    static const std::unordered_map<std::string, TokenType> keywords{
        {"start", TokenType::Start},
        {"int", TokenType::NativeInt}, {"uint", TokenType::NativeUInt},
        {"unsigned", TokenType::RemovedUnsigned},
        {"float", TokenType::NativeFloat},
        {"int8", TokenType::Int8}, {"uint8", TokenType::UInt8},
        {"int16", TokenType::Int16}, {"uint16", TokenType::UInt16},
        {"int32", TokenType::Int32}, {"uint32", TokenType::UInt32},
        {"int64", TokenType::Int64}, {"uint64", TokenType::UInt64},
        {"fp32", TokenType::FP32}, {"fp64", TokenType::FP64},
        {"bool", TokenType::Bool},
        {"strg", TokenType::StrgType},
        {"list", TokenType::ListType}, {"dict", TokenType::DictType},
        {"range", TokenType::RangeType},
        {"buffer", TokenType::BufferType}, {"handle", TokenType::HandleType},
        {"any", TokenType::AnyType}, {"type", TokenType::TypeType},
        {"if", TokenType::If},
        {"else", TokenType::Else}, {"while", TokenType::While},
        {"do", TokenType::Do}, {"for", TokenType::For},
        {"in", TokenType::In}, {"is", TokenType::Is}, {"break", TokenType::Break},
        {"continue", TokenType::Continue}, {"and", TokenType::And},
        {"switch", TokenType::Switch}, {"case", TokenType::Case},
        {"default", TokenType::Default},
        {"or", TokenType::Or}, {"not", TokenType::Bang},
        {"print", TokenType::Print}, {"raise", TokenType::Raise},
        {"try", TokenType::Try}, {"except", TokenType::Except},
        {"finally", TokenType::Finally}, {"class", TokenType::Class},
        {"namespace", TokenType::Namespace}, {"include", TokenType::Include},
        {"inline", TokenType::Inline},
        {"import", TokenType::Import}, {"as", TokenType::As},
        {"from", TokenType::From},
        {"public", TokenType::Public}, {"protected", TokenType::Protected},
        {"private", TokenType::Private},
        {"const", TokenType::Const},
        {"virtual", TokenType::Virtual},
        {"super", TokenType::Super},
        {"null", TokenType::Null},
        {"true", TokenType::True}, {"false", TokenType::False},
        {"return", TokenType::Return}, {"void", TokenType::Void}
    };
    const auto found = keywords.find(normalized);
    if (found != keywords.end() && found->second == TokenType::Inline) {
        inlineHeader_ = true;
    }
    return makeToken(found == keywords.end() ? TokenType::Identifier : found->second,
                     std::move(text), location);
}

Token Lexer::scanInlineBody(SourceLocation location) {
    advance();
    std::size_t braceDepth = 1;
    std::string body;
    const auto append = [&]() { body.push_back(advance()); };

    while (!atEnd()) {
        if (peek() == '"' || peek() == '\'') {
            const char quote = peek();
            append();
            bool closed = false;
            while (!atEnd()) {
                const char value = peek();
                append();
                if (value == '\\' && !atEnd()) {
                    append();
                } else if (value == quote) {
                    closed = true;
                    break;
                }
            }
            if (!closed) {
                throw DiagnosticError(location, "unterminated string in inline C block");
            }
            continue;
        }
        if (peek() == '/' && peek(1) == '/') {
            append();
            append();
            while (!atEnd() && peek() != '\n') append();
            continue;
        }
        if (peek() == '/' && peek(1) == '*') {
            append();
            append();
            bool closed = false;
            while (!atEnd()) {
                if (peek() == '*' && peek(1) == '/') {
                    append();
                    append();
                    closed = true;
                    break;
                }
                append();
            }
            if (!closed) {
                throw DiagnosticError(location, "unterminated comment in inline C block");
            }
            continue;
        }
        if (peek() == '{') {
            ++braceDepth;
            append();
            continue;
        }
        if (peek() == '}') {
            advance();
            if (--braceDepth == 0) {
                inlineHeader_ = false;
                return makeToken(TokenType::InlineBody, std::move(body), location);
            }
            body.push_back('}');
            continue;
        }
        append();
    }
    throw DiagnosticError(location, "unterminated inline C block");
}

Token Lexer::scanString(char quote, SourceLocation location) {
    advance();
    std::string value;
    while (!atEnd() && peek() != quote) {
        if (peek() == '\n' || peek() == '\r') {
            throw DiagnosticError(currentLocation(), "newline in string literal");
        }
        if (quote == '"' && peek() == '\\') {
            advance();
            if (atEnd()) {
                throw DiagnosticError(location, "unterminated escape sequence");
            }
            const char escaped = advance();
            switch (escaped) {
            case 'e': value.push_back('\x1b'); break;
            case 'n': value.push_back('\n'); break;
            case 'r': value.push_back('\r'); break;
            case 't': value.push_back('\t'); break;
            case '\\': value.push_back('\\'); break;
            case '"': value.push_back('"'); break;
            default:
                throw DiagnosticError(currentLocation(), "unsupported string escape");
            }
        } else {
            value.push_back(advance());
        }
    }
    if (atEnd()) {
        throw DiagnosticError(location, "unterminated string literal");
    }
    advance();
    if (!isValidUtf8(value)) {
        throw DiagnosticError(location, "string literal is not valid UTF-8");
    }
    return makeToken(TokenType::String, std::move(value), std::move(location), quote == '"');
}

std::vector<Token> Lexer::tokenize() {
    std::vector<Token> tokens;
    std::size_t parenthesisDepth = 0;
    while (!atEnd()) {
        skipTrivia(tokens, parenthesisDepth);
        if (atEnd()) {
            break;
        }
        const auto location = currentLocation();
        const char value = peek();
        if (inlineHeader_ && value == '{') {
            tokens.push_back(scanInlineBody(location));
            continue;
        }
        if (value == '\n') {
            advance();
            if (parenthesisDepth == 0) {
                tokens.push_back(makeToken(TokenType::Newline, "\n", location));
            }
            continue;
        }
        if (isIdentifierStart(value) || (value >= '0' && value <= '9') ||
            (value == '.' && peek(1) >= '0' && peek(1) <= '9')) {
            tokens.push_back(scanIdentifierOrInteger());
            continue;
        }
        if (value == '"' || value == '\'') {
            tokens.push_back(scanString(value, location));
            continue;
        }
        advance();
        TokenType type;
        switch (value) {
        case ';':
            throw DiagnosticError(location,
                                  "unknown character ';': ';' is not a comment; use '#' or '//'");
        case '{': type = TokenType::LeftBrace; break;
        case '}': type = TokenType::RightBrace; break;
        case '(': type = TokenType::LeftParen; break;
        case ')': type = TokenType::RightParen; break;
        case '[': type = TokenType::LeftBracket; break;
        case ']': type = TokenType::RightBracket; break;
        case ',': type = TokenType::Comma; break;
        case '.':
            type = peek() == '.' ? (advance(), TokenType::DotDot) : TokenType::Dot;
            break;
        case ':': type = TokenType::Colon; break;
        case '+':
            type = peek() == '=' ? (advance(), TokenType::PlusEqual) : TokenType::Plus;
            break;
        case '-':
            type = peek() == '=' ? (advance(), TokenType::MinusEqual) : TokenType::Minus;
            break;
        case '*':
            type = peek() == '=' ? (advance(), TokenType::StarEqual) : TokenType::Star;
            break;
        case '/':
            type = peek() == '=' ? (advance(), TokenType::SlashEqual) : TokenType::Slash;
            break;
        case '%':
            type = peek() == '=' ? (advance(), TokenType::PercentEqual) : TokenType::Percent;
            break;
        case '&':
            type = peek() == '&' ? (advance(), TokenType::AndAnd) :
                   peek() == '=' ? (advance(), TokenType::AmpersandEqual) :
                                   TokenType::Ampersand;
            break;
        case '|':
            type = peek() == '|' ? (advance(), TokenType::OrOr) :
                   peek() == '=' ? (advance(), TokenType::PipeEqual) : TokenType::Pipe;
            break;
        case '^':
            type = peek() == '=' ? (advance(), TokenType::CaretEqual) : TokenType::Caret;
            break;
        case '~': type = TokenType::Tilde; break;
        case '!':
            type = peek() == '=' ? (advance(), TokenType::BangEqual) : TokenType::Bang;
            break;
        case '=':
            type = peek() == '=' ? (advance(), TokenType::EqualEqual) : TokenType::Equal;
            break;
        case '<':
            if (peek() == '<') {
                advance();
                type = peek() == '=' ? (advance(), TokenType::ShiftLeftEqual) :
                                       TokenType::ShiftLeft;
            } else type = peek() == '=' ? (advance(), TokenType::LessEqual) : TokenType::Less;
            break;
        case '>':
            if (peek() == '>') {
                advance();
                type = peek() == '=' ? (advance(), TokenType::ShiftRightEqual) :
                                       TokenType::ShiftRight;
            } else type = peek() == '=' ? (advance(), TokenType::GreaterEqual) : TokenType::Greater;
            break;
        default:
            throw DiagnosticError(location, "unexpected character");
        }
        if (type == TokenType::LeftParen || type == TokenType::LeftBracket) {
            ++parenthesisDepth;
        } else if ((type == TokenType::RightParen || type == TokenType::RightBracket) &&
                   parenthesisDepth > 0) {
            --parenthesisDepth;
        }
        std::string text(1, value);
        if (type == TokenType::PlusEqual || type == TokenType::MinusEqual ||
            type == TokenType::StarEqual || type == TokenType::SlashEqual ||
            type == TokenType::PercentEqual || type == TokenType::AmpersandEqual ||
            type == TokenType::PipeEqual || type == TokenType::CaretEqual) {
            text.push_back('=');
        } else if (type == TokenType::ShiftLeft || type == TokenType::ShiftRight ||
                   type == TokenType::ShiftLeftEqual || type == TokenType::ShiftRightEqual) {
            text.push_back(value);
            if (type == TokenType::ShiftLeftEqual || type == TokenType::ShiftRightEqual)
                text.push_back('=');
        } else if (type == TokenType::BangEqual || type == TokenType::EqualEqual ||
            type == TokenType::LessEqual || type == TokenType::GreaterEqual ||
            type == TokenType::AndAnd || type == TokenType::OrOr) {
            if (type == TokenType::AndAnd || type == TokenType::OrOr) {
                text.push_back(value);
            } else {
                text.push_back('=');
            }
        }
        tokens.push_back(makeToken(type, std::move(text), location));
    }
    tokens.push_back(makeToken(TokenType::End, "", currentLocation()));
    return tokens;
}

